-- Dairy products, eggs and margarine (storage group of each restaurant) and the supplier Bourassa (between the orders with Agropur).
INSERT INTO suppliers (client_id, name, notes, position) SELECT 1, 'Bourassa', 'Dépannage entre les commandes d’Agropur', COALESCE((SELECT MAX(position) FROM suppliers WHERE client_id = 1), 0) + 1 WHERE EXISTS (SELECT 1 FROM clients WHERE id = 1) AND NOT EXISTS (SELECT 1 FROM suppliers WHERE client_id = 1 AND name = 'Bourassa');
INSERT INTO ingredient_groups (restaurant_id, name_fr, name_en, post_id, position) SELECT r.id, 'Réserve et général', 'Storage and general', NULL, COALESCE((SELECT MAX(position) FROM ingredient_groups WHERE restaurant_id = r.id), 0) + 1 FROM restaurants r WHERE (r.name LIKE '%Sauveur%' OR r.name LIKE '%Agathe%') AND NOT EXISTS (SELECT 1 FROM ingredient_groups g WHERE g.restaurant_id = r.id AND g.name_fr = 'Réserve et général');
INSERT INTO ingredients (group_id, name, location, category, position) SELECT g.id, 'Lait 2% (4L en sac)', 'fridge', 'dairy', COALESCE((SELECT MAX(i.position) FROM ingredients i WHERE i.group_id = g.id), 0) + 1 FROM ingredient_groups g JOIN restaurants r ON r.id = g.restaurant_id WHERE g.name_fr = 'Réserve et général' AND (r.name LIKE '%Sauveur%' OR r.name LIKE '%Agathe%') AND NOT EXISTS (SELECT 1 FROM ingredients i WHERE i.group_id = g.id AND i.name = 'Lait 2% (4L en sac)');
INSERT OR IGNORE INTO ingredient_suppliers (ingredient_id, supplier_id) SELECT i.id, s.id FROM ingredients i JOIN ingredient_groups g ON g.id = i.group_id JOIN restaurants r ON r.id = g.restaurant_id JOIN suppliers s ON s.client_id = r.client_id AND s.name LIKE 'Agropur%' WHERE g.name_fr = 'Réserve et général' AND i.name = 'Lait 2% (4L en sac)';
INSERT OR IGNORE INTO ingredient_suppliers (ingredient_id, supplier_id) SELECT i.id, s.id FROM ingredients i JOIN ingredient_groups g ON g.id = i.group_id JOIN restaurants r ON r.id = g.restaurant_id JOIN suppliers s ON s.client_id = r.client_id AND s.name LIKE 'Bourassa%' WHERE g.name_fr = 'Réserve et général' AND i.name = 'Lait 2% (4L en sac)';
